import { RiskLevel, TrustProfile, WalletActivity } from "../types/trust.types";

const calculateRisk = \(score: number\): RiskLevel => {
  if \(score >= 80\) return "LOW";
  if \(score >= 50\) return "MEDIUM";
  if \(score >= 25\) return "HIGH";
  return "CRITICAL";
};

export const computeTrustProfile = \(
  wallet: string,
  activity: WalletActivity,
  isNinja: boolean
\): TrustProfile => {
  let score = 50;

  if \(activity.tx_count > 100\) score += 15;
  if \(activity.volume_usd > 10000\) score += 10;
  if \(activity.unique_pairs > 5\) score += 5;
  if \(isNinja\) score += 20;

  score = Math.min\(100, Math.max\(0, score\)\);

  const tags: string[] = [];
  if \(isNinja\) tags.push\("N1NJ4_HOLDER"\);
  if \(activity.tx_count === 0\) tags.push\("NEW_USER"\);
  if \(activity.tx_count > 500\) tags.push\("POWER_TRADER"\);

  return {
    wallet,
    verified_ninja: isNinja,
    trust_score: score,
    risk: calculateRisk\(score\),
    bot_probability: 0,
    tags,
    tx_count: activity.tx_count,
    volume_usd: activity.volume_usd,
    last_active: activity.last_active,
  };
};
ENDOFFILE)

