import cron from "node-cron";
import { Wallet } from "../models/Wallet.model";
import { fetchWalletActivity } from "../services/injective.service";
import { checkN1NJ4Holder } from "../services/n1nj4.service";
import { computeTrustProfile } from "../services/scoring.service";

export const startSyncJob = \(\): void => {
  cron.schedule\("*/30 * * * *", async \(\) => {
    console.log\("[sync] Starting wallet sync..."\);
    try {
      const wallets = await Wallet.find\({}\);
      for \(const w of wallets\) {
        const activity = await fetchWalletActivity\(w.address\);
        const holder = await checkN1NJ4Holder\(w.address\);
        const profile = computeTrustProfile\(w.address, activity, !!holder\);

        await Wallet.updateOne\(
          { address: w.address },
          {
            trust_score: profile.trust_score,
            risk: profile.risk,
            bot_probability: profile.bot_probability,
            tags: profile.tags,
            verified_ninja: profile.verified_ninja,
            tx_count: profile.tx_count,
            volume_usd: profile.volume_usd,
            last_active: profile.last_active,
          }
        \);
      }
      console.log\("[sync] Synced ${wallets.length} wallets"\);
    } catch \(err\) {
      console.error\("[sync] Error:", err\);
    }
  }\);
};
ENDOFFILE)

